use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SmtpOutboundConfigListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SmtpOutboundConfigVisibilityService $visibility,
        private readonly SmtpOutboundConfigReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Smtp outbound config");
        $span = $this->startSpan("Check allow of list usecase for Smtp outbound config");
        try {
            $result = $this->dispatcher->dispatch(new SmtpOutboundConfigListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(SmtpOutboundConfigFilter $filter): int
    {
        $this->logDebug("Run list usecase for Smtp outbound config");
        $span = $this->startSpan("Run list usecase for Smtp outbound config");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Smtp outbound config');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(SmtpOutboundConfigFilter $filter, ?SmtpOutboundConfigCursor $cursor = null): SmtpOutboundConfigAttributesSlide
    {
        $this->logDebug("Run list usecase for Smtp outbound config");
        $span = $this->startSpan("Run list usecase for Smtp outbound config");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new SmtpOutboundConfigAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
